/* Deck engine + slide builders. Offline: everything comes from js/deck_data.js (generated by deck_charts.py).
   Keys: ←/→, PgUp/PgDn, Space, Home/End, 1–9 jump · N speaker notes. On step slides (slide 4) →/Space advance the
   steps first, then the slide. URL: #slide=N (also #deck=…&slide=N), &step=K, ?shot=1 (no transitions or autoplay;
   step slides show their final frame, replays their key frame). */
(function () {
  "use strict";
  const D = window.DECK_DATA || { svgs: {}, kpi: {}, replays: {}, pricing: {}, placeholders: [] };
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
  const html = document.documentElement;
  if (/[?&]shot=1/.test(location.search)) html.classList.add("shot");
  const fmt = (x, d = 0) => (x === null || x === undefined || !isFinite(x) ? "–" : Number(x).toLocaleString("en-US", { maximumFractionDigits: d, minimumFractionDigits: d }));

  /* ------------------------------------------------------------ scale + navigation */
  const stage = $(".stage");
  const slides = $$(".slide");
  const pager = $(".pager");
  function fit() {
    const s = Math.min(window.innerWidth / 1920, window.innerHeight / 1080);
    html.style.setProperty("--s", String(s > 0 ? s : 1));
  }
  window.addEventListener("resize", fit);
  fit();
  let cur = 0, pagerT = 0;
  function params() {
    const h = location.hash.replace(/^#/, "");
    const p = new URLSearchParams(h.includes("=") ? h : `slide=${h}`);
    return p;
  }
  function go(i, push = true, fromEnd = false) {
    const prev = cur;
    cur = Math.max(0, Math.min(slides.length - 1, i));
    const st = slides[cur].dataset.steps;
    if (st && push) setStep(slides[cur], fromEnd || (cur < prev && !html.classList.contains("shot")) ? +st - 1 : 0);
    slides.forEach((s, k) => { s.classList.toggle("is-active", k === cur); s.setAttribute("aria-hidden", k === cur ? "false" : "true"); });
    if (push) {
      const p = params();
      p.set("slide", String(cur + 1));
      p.delete("step");
      try { history.replaceState(null, "", "#" + p.toString()); } catch (e) { /* file:// on some browsers */ }
    }
    pager.textContent = `${cur + 1} / ${slides.length}`;
    pager.classList.add("on");
    clearTimeout(pagerT);
    pagerT = setTimeout(() => pager.classList.remove("on"), 1400);
    renderNotes();
    onSlide(cur);
  }
  function fromHash() {
    const p = params();
    const n = parseInt(p.get("slide") || "1", 10);
    const i = isFinite(n) ? n - 1 : 0;
    const sl = slides[Math.max(0, Math.min(slides.length - 1, i))];
    if (sl && sl.dataset.steps) {
      const last = +sl.dataset.steps - 1;
      setStep(sl, p.get("step") !== null ? Math.max(0, Math.min(last, +p.get("step"))) : html.classList.contains("shot") ? last : 0);
    }
    go(i, false);
  }
  window.addEventListener("hashchange", fromHash);
  document.addEventListener("keydown", (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const t = e.target;
    if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA")) return;
    const k = e.key;
    const sl = slides[cur];
    if (["ArrowRight", "PageDown", " ", "ArrowDown"].includes(k)) {
      e.preventDefault();
      if (sl.dataset.steps && sl._step < +sl.dataset.steps - 1) setStep(sl, sl._step + 1); else go(cur + 1);
    } else if (["ArrowLeft", "PageUp", "ArrowUp"].includes(k)) {
      e.preventDefault();
      if (sl.dataset.steps && sl._step > 0) setStep(sl, sl._step - 1); else go(cur - 1, true, true);
    }
    else if (k === "Home") go(0);
    else if (k === "End") go(slides.length - 1);
    else if (/^[1-9]$/.test(k)) go(parseInt(k, 10) - 1);
    else if (k === "n" || k === "N") $(".notes-panel").classList.toggle("on");
  });

  function renderNotes() {
    const p = $(".notes-panel");
    const n = slides[cur].querySelector(".notes");
    p.innerHTML = `<h5>Slide ${cur + 1} · speaker notes and sources</h5>` + (n ? n.innerHTML : "");
  }

  /* ------------------------------------------------------------ slide 1: idle host strips */
  function strip(host, spec) {
    // spec: ncores, l3 (cores per domain), vllm cores, reserve cores; idle = everything else (what colo fills)
    const box = $(host);
    let out = "";
    let c0 = 0;
    spec.l3.forEach((n, d) => {
      if (d) out += '<i class="gap"></i><i class="gap"></i>';
      for (let c = c0; c < c0 + n; c++) {
        const cls = spec.vllm.includes(c) ? "v" : spec.reserve.includes(c) ? "r" : "";
        out += `<i class="${cls}"></i><i class="${cls}"></i>`;
      }
      c0 += n;
    });
    box.innerHTML = out;
  }

  /* ------------------------------------------------------------ slide 2: to-scale host diagrams */
  const C = { blue: "#5A82B3", red: "#E2625E", yellow: "#E2B540", green: "#489B6E", ink: "#111314", warm: "#A1A39A", ground: "#FFFDF7" };
  const mix = (c, p) => `color-mix(in srgb, ${C[c]} ${p}%, ${C.ground})`;
  function hostSVG(h, x0) {
    const P = 28, TW = 24, TH = 28, DP = 10, DG = 14, PP = 14;
    const doms = h.l3.map((n) => n * P - 4 + 2 * DP);
    const pkgW = doms.reduce((a, b) => a + b, 0) + DG * (doms.length - 1) + 2 * PP;
    let s = `<g transform="translate(${x0},0)">`;
    s += `<text class="h" x="0" y="26">${h.name}</text>`;
    s += `<text class="sub" x="0" y="56">${h.cpu} · ${h.cores} cores × 2 threads · ${h.l3.join("/")} cores per L3 · 1 NUMA node</text>`;
    s += `<rect x="0" y="78" width="${pkgW}" height="206" rx="20" fill="${mix("warm", 10)}" stroke="${C.ink}" stroke-opacity=".55" stroke-width="2"/>`;
    let x = PP, core = 0;
    h.l3.forEach((n, d) => {
      const w = doms[d];
      s += `<rect x="${x}" y="94" width="${w}" height="176" rx="14" fill="${C.ground}" stroke="${C.ink}" stroke-opacity=".25" stroke-width="1.5"/>`;
      s += `<text class="lblb" x="${x + DP}" y="118">L3 ${d}</text><text class="lbl" x="${x + w - DP}" y="118" text-anchor="end">${n} cores</text>`;
      for (let c = 0; c < n; c++, core++) {
        const col = h.vllm.includes(core) ? C.blue : h.reserve.includes(core) ? C.warm : C.green;
        for (let t = 0; t < 2; t++) s += `<rect x="${x + DP + c * P}" y="${130 + t * (TH + 4)}" width="${TW}" height="${TH}" rx="6" fill="${col}"/>`;
      }
      s += `<rect x="${x + DP}" y="200" width="${w - 2 * DP}" height="56" rx="10" fill="${mix("red", 14)}" stroke="${C.red}" stroke-width="2" stroke-dasharray="6 5"/>`;
      s += `<text class="lblb" x="${x + w / 2}" y="223" text-anchor="middle">${h.l3mib} MiB L3</text><text class="lbl" x="${x + w / 2}" y="246" text-anchor="middle">shared by ${n} cores</text>`;
      x += w + DG;
    });
    // memory (one controller domain, NUMA 1); PCIe runs beside it to the accelerator
    const memW = pkgW - 170;
    s += `<rect x="0" y="300" width="${memW}" height="56" rx="14" fill="${mix("red", 14)}" stroke="${C.red}" stroke-width="2" stroke-dasharray="6 5"/>`;
    s += `<text class="lblb" x="20" y="334">Memory ${h.mem}</text><text class="lbl" x="${memW - 20}" y="334" text-anchor="end">bandwidth shared by all ${h.cores * 2} vCPU</text>`;
    s += `<line x1="${memW / 2}" y1="284" x2="${memW / 2}" y2="300" stroke="${C.ink}" stroke-width="3"/>`;
    // PCIe to the accelerator; box width proportional to accelerator memory
    const px = pkgW - 85, aw = h.accGB * 5.2;
    s += `<line x1="${px}" y1="284" x2="${px}" y2="410" stroke="${C.ink}" stroke-width="3"/>`;
    s += `<text class="lbl" x="${px + 12}" y="340">PCIe</text>`;
    const ax = Math.min(px - aw / 2, pkgW - aw);
    s += `<rect x="${Math.max(0, ax)}" y="410" width="${aw}" height="96" rx="18" fill="${mix("blue", 22)}" stroke="${C.blue}" stroke-width="2.5"/>`;
    const tx = Math.max(0, ax) - 18;
    s += `<text class="h" x="${tx}" y="450" text-anchor="end">${h.acc}</text><text class="sub" x="${tx}" y="480" text-anchor="end">${h.accMem}</text>`;
    // what runs where
    const items = [["blue", `vLLM ${h.vllm.length * 2} vCPU`], ["green", `backfill ${h.bf * 2} vCPU`], ["warm", `shared ${h.reserve.length * 2} vCPU`]];
    let lx = 0;
    items.forEach(([c, t]) => { s += `<rect x="${lx}" y="534" width="18" height="18" rx="5" fill="${C[c]}"/><text class="lbl" x="${lx + 26}" y="550">${t}</text>`; lx += 26 + t.length * 9.6 + 30; });
    s += "</g>";
    return s;
  }

  /* ------------------------------------------------------------ slide 3: GKE block diagram */
  const OWN = { gke: "blue", k8s: "warm", recipe: "green" };
  function box(x, y, w, h, owner, title, lines = [], opt = {}) {
    const c = OWN[owner];
    let s = `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="18" fill="${mix(c, owner === "k8s" ? 16 : 12)}" stroke="${owner === "k8s" ? C.ink : C[c]}" stroke-opacity="${owner === "k8s" ? 0.55 : 1}" stroke-width="2.5"/>`;
    s += `<text x="${x + 20}" y="${y + 34}" style="font-size:21px;font-weight:700">${title}</text>`;
    lines.forEach((l, i) => { s += `<text x="${x + 20}" y="${y + 64 + i * 26}" style="font-size:18px" fill="${C.ink}" fill-opacity=".78">${l}</text>`; });
    return s;
  }
  function chip(x, y, w, h, col, title, sub) {
    let s = `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${C.ground}" stroke="${C[col]}" stroke-width="2"/>`;
    s += `<circle cx="${x + 18}" cy="${y + 22}" r="7" fill="${C[col]}"/>`;
    s += `<text x="${x + 34}" y="${y + 28}" style="font-size:17.5px;font-weight:700">${title}</text>`;
    if (sub) s += `<text x="${x + 34}" y="${y + 50}" style="font-size:17px" fill="${C.ink}" fill-opacity=".75">${sub}</text>`;
    return s;
  }
  function arrow(pts, dashed, label, lx, ly, anchor = "start") {
    const d = pts.map((p, i) => `${i ? "L" : "M"}${p[0]},${p[1]}`).join(" ");
    let s = `<path d="${d}" fill="none" stroke="${C.ink}" stroke-width="2.2" ${dashed ? 'stroke-dasharray="7 6"' : ""} marker-end="url(#ah)"/>`;
    if (label) s += `<text x="${lx}" y="${ly}" text-anchor="${anchor}" style="font-size:17px;font-weight:600" fill="${C.ink}">${label}</text>`;
    return s;
  }
  function gkeSVG() {
    let s = `<defs><marker id="ah" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${C.ink}"/></marker></defs>`;
    // legend
    const lg = [["blue", "GKE (managed)"], ["warm", "Kubernetes"], ["green", "this recipe (YAML)"]];
    let lx = 900;
    lg.forEach(([c, t]) => { s += `<rect x="${lx}" y="2" width="20" height="20" rx="6" fill="${mix(c, 30)}" stroke="${c === "warm" ? C.ink : C[c]}" stroke-opacity="${c === "warm" ? .55 : 1}" stroke-width="2"/><text x="${lx + 30}" y="18" style="font-size:17px">${t}</text>`; lx += 40 + t.length * 9 + 26; });
    s += `<path d="M1520,12 L1572,12" stroke="${C.ink}" stroke-width="2.2" stroke-dasharray="7 6"/><text x="1580" y="18" style="font-size:17px">decides</text>`;
    s += `<path d="M1520,40 L1572,40" stroke="${C.ink}" stroke-width="2.2"/><text x="1580" y="46" style="font-size:17px">places</text>`;
    s += `<text x="0" y="20" style="font-size:19px;font-weight:700" fill="${C.ink}" fill-opacity=".72">CONTROL PATH · how many pods</text>`;
    // control path
    s += box(0, 56, 280, 104, "recipe", "vLLM /metrics", ["requests per second"]);
    s += box(0, 196, 280, 136, "k8s", "kube-state-metrics", ["pods + Deployments,", "scraped every 5 s"]);
    s += box(340, 56, 330, 104, "gke", "Managed Prometheus", ["metrics, 5 s"]);
    s += box(340, 196, 330, 136, "gke", "AutoscalingMetric", ["PromQL per service:", "colo_overflow_needed =", "backfill desired − effective"]);
    s += box(730, 56, 330, 104, "k8s", "vLLM HPA", ["request rate, 700 req/s per pod"]);
    s += box(730, 196, 330, 136, "k8s", "Overflow HPAs", ["External metric, one per service", "minReplicas 0 · tolerance 0", "follows demand in ~15 s"]);
    s += box(1120, 56, 600, 276, "recipe", "Deployments", []);
    s += chip(1140, 104, 560, 60, "blue", "vLLM · namespace inference", "1 GPU or TPU · 8 vCPU, Guaranteed");
    s += chip(1140, 176, 560, 60, "green", "‹svc›-backfill · replicas = the whole demand", "priority −100 · podAffinity to vLLM · integer CPU");
    s += chip(1140, 248, 560, 60, "red", "‹svc›-overflow · runs what does not fit", "ComputeClass n4d-cpu · priority 0");
    s += arrow([[280, 108], [340, 108]], true);
    s += arrow([[280, 264], [310, 264], [310, 130], [340, 130]], true);
    s += arrow([[505, 160], [505, 196]], true);
    s += arrow([[670, 230], [700, 230], [700, 108], [730, 108]], true);
    s += arrow([[670, 278], [730, 278]], true);
    s += arrow([[1060, 108], [1100, 108], [1100, 134], [1140, 134]], true);
    s += arrow([[1060, 278], [1140, 278]], true);
    // data path
    s += `<text x="0" y="400" style="font-size:19px;font-weight:700" fill="${C.ink}" fill-opacity=".72">DATA PATH · where pods run</text>`;
    s += box(0, 424, 460, 316, "k8s", "Admission: colo-g4-guard", [
      "ValidatingAdmissionPolicy:",
      "• memory-heavy services never on",
      "   accelerator hosts",
      "• only serving may ask for GPU/TPU",
      "• customer DaemonSets on accelerator",
      "   hosts only from labelled namespaces"]);
    s += box(520, 424, 400, 136, "k8s", "kube-scheduler", ["backfill binds only next to vLLM", "PriorityClasses: backfill −100, overflow 0", "static CPU manager: whole cores"]);
    s += box(520, 600, 400, 140, "gke", "Cluster Autoscaler", ["+ ComputeClasses: accelerator class", "(consolidation 3 min) and n4d-cpu", "ignores Pending priority −100"]);
    s += box(980, 424, 470, 316, "k8s", "Accelerator node · G4 or TPU v6e", []);
    s += chip(1000, 474, 430, 60, "blue", "vLLM", "8 exclusive vCPU (cores 1–4, one L3)");
    s += chip(1000, 542, 430, 60, "green", "backfill pods", "2 vCPU each = one whole core, exclusive");
    s += chip(1000, 610, 430, 60, "warm", "shared-core reserve DaemonSet", "2 CPU, Burstable, keeps kubelet fed");
    s += chip(1000, 678, 430, 50, "warm", "customer DaemonSets (shared cores)", "");
    s += box(1490, 424, 230, 316, "k8s", "N4D nodes", []);
    s += chip(1505, 474, 200, 60, "red", "overflow pods", "paid, priority 0");
    s += chip(1505, 542, 200, 60, "yellow", "warm buffer", "1 pod, preempted");
    s += arrow([[1420, 332], [1420, 376], [720, 376], [720, 424]], false, "replicas", 1080, 368);
    s += arrow([[460, 492], [520, 492]], false, "admits", 466, 482);
    s += arrow([[920, 492], [980, 492]], false);
    s += arrow([[920, 530], [950, 530], [950, 404], [1605, 404], [1605, 424]], false, "no room next to vLLM → overflow on N4D", 1590, 396, "end");
    s += arrow([[720, 560], [720, 600]], false, "Pending pods", 732, 586);
    s += arrow([[920, 680], [980, 680]], false, "adds /", 926, 708);
    s += `<text x="926" y="728" style="font-size:15.5px;font-weight:600">removes</text>`;
    return s;
  }

  const players = {};
  function onSlide(i) {
    Object.values(players).forEach((p) => p.pause());
    if (html.classList.contains("shot")) return;
    const p = players[slides[i].dataset.replay];
    if (p) p.restart(); // a replay always starts clean when its slide becomes visible
  }
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) Object.values(players).forEach((p) => p.pause());
    else onSlide(cur);
  });
  window.DeckPlayers = players; // used by the playback benchmark (bench_replay.py)

  const cell = (v, l) => `<div class="kpi"><b>${v}</b><span>${l}</span></div>`;
  function kpis(host, k) {
    const el = $(host);
    if (!el) return;
    k = k || {};
    el.innerHTML =
      cell(k.ttft_ratio ? `${fmt(k.ttft_ratio, 2)}×` : "–", k.ttft_ratio ? `TTFT p99 with the node full (${fmt(k.ttft_solo_ms)} → ${fmt(k.ttft_full_ms)} ms)` : "TTFT p99 with the node full") +
      cell(k.node_busy_full !== undefined ? `${fmt(k.node_busy_solo)} → ${fmt(k.node_busy_full)} %` : "–", "host CPU busy, alone → node full") +
      cell(k.spike_covered_s ? `${fmt(k.spike_covered_s)} s` : "–", "CPU spike fully covered (N4D boot)") +
      cell(k.scalein_ready_pct !== undefined ? `${fmt(k.scalein_ready_pct, Number.isInteger(k.scalein_ready_pct) ? 0 : 1)} %` : "–", "CPU pods Ready ≥ demand during scale-in");
  }
  function kpisExp() {
    const el = $("#kpi-exp"), e = (D.kpi || {}).exp || {}, nb = (D.kpi || {}).exp_node_busy || [];
    if (!el) return;
    el.innerHTML =
      cell(nb.length ? `${fmt(nb[0])} → ${fmt(nb[2])} %` : "–", "host CPU busy, vLLM alone → 95 % colo") +
      cell(`+${fmt(e.ttft_p99_integer)} %`, "TTFT p99 next to integer work") +
      cell(`+${fmt(e.ttft_p99_fotonik)} %`, "TTFT p99 next to memory-bandwidth work") +
      cell(`±${fmt(e.tok_s_max_abs, 1)} %`, "tokens/s, every cell");
  }

  /* ------------------------------------------------------------ slide 3: step-through flow */
  function tiles(x0, y0, cols, rows, pitch, colour, step, d, opts = {}) {
    let s = "";
    for (let c = 0; c < cols; c++) for (let r = 0; r < rows; r++) {
      const col = colour(c, r);
      if (!col) continue;
      const st = typeof step === "function" ? step(c, r) : step;
      const attrs = st !== null && st !== undefined ? ` data-s="${st}" style="--d:${typeof d === "function" ? d(c, r) : d}ms"` : "";
      s += col === "outline"
        ? `<rect x="${x0 + c * pitch}" y="${y0 + r * pitch}" width="${pitch - 6}" height="${pitch - 6}" rx="6" fill="none" stroke="${C.ink}" stroke-opacity=".3" stroke-width="2" stroke-dasharray="${opts.dash || "none"}"${attrs}/>`
        : `<rect x="${x0 + c * pitch}" y="${y0 + r * pitch}" width="${pitch - 6}" height="${pitch - 6}" rx="6" fill="${C[col]}"${attrs}/>`;
    }
    return s;
  }
  function flowSVG() {
    const fbox = (x, y, w, h, fill, stroke, so = 1) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="22" fill="${fill}" stroke="${stroke}" stroke-opacity="${so}" stroke-width="3"/>`;
    const sig = (st, d, path, label, lx, ly, anchor = "start") =>
      `<path class="sig" data-s="${st}" style="--d:${d}ms" d="${path}" marker-end="url(#fah)"/>` +
      (label ? `<text class="t3 lab" data-s="${st}" style="--d:${d}ms" x="${lx}" y="${ly}" text-anchor="${anchor}">${label}</text>` : "");
    let s = `<defs><marker id="fah" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${C.ink}"/></marker></defs>`;
    // GKE autoscaling decides
    s += fbox(360, 0, 1304, 88, mix("blue", 16), C.blue);
    s += `<text class="t1" x="388" y="40">GKE autoscaling decides</text><text class="t2" x="388" y="72">metrics → HPAs → Cluster Autoscaler</text>`;
    s += `<g data-s="1" style="--d:700ms"><rect x="770" y="16" width="420" height="56" rx="28" fill="${C.ground}" stroke="${C.blue}" stroke-width="2.5"/><text class="t3" x="980" y="51" text-anchor="middle">vLLM HPA 1 → 2 · +1 accelerator node</text></g>`;
    s += `<g data-s="2" style="--d:700ms"><rect x="1214" y="16" width="430" height="56" rx="28" fill="${C.ground}" stroke="${C.red}" stroke-width="2.5"/><text class="t3" x="1429" y="51" text-anchor="middle">Overflow HPA 0 → 6 · +1 N4D node</text></g>`;
    // inputs
    s += fbox(0, 130, 300, 150, mix("warm", 14), C.ink, 0.45);
    s += `<text class="t1" x="24" y="176">LLM traffic</text><text class="t2" x="24" y="208">requests to vLLM</text>`;
    s += `<text class="t3" data-s="1" x="24" y="252" fill="${C.blue}" style="fill:${C.blue}">rises ↑</text>`;
    s += fbox(0, 312, 300, 168, mix("warm", 14), C.ink, 0.45);
    s += `<text class="t1" x="24" y="358">CPU demand</text><text class="t2" x="24" y="390">your services' pods</text>`;
    s += `<text class="t3" data-s="2" x="24" y="428" style="fill:${C.red}">rises ↑ · 6 pods don't fit</text>`;
    s += tiles(24, 440, 6, 1, 32, () => "outline", 2, (c) => 200 + c * 60, { dash: "5 4" });
    // accelerator host #1: 12 x 4 tiles = 48 vCPU
    const hostTiles = (x0, st, dV, dG) => tiles(x0, 222, 12, 4, 32, (c) => (c < 2 ? "blue" : c === 11 ? "warm" : "green"),
      st, (c, r) => (c < 2 ? dV : c === 11 ? dV : dG + (c * 4 + r) * 25));
    s += fbox(360, 120, 440, 360, C.ground, C.ink, 0.55);
    s += `<text class="t1" x="388" y="164">Accelerator host</text><text class="t2" x="388" y="196">vLLM + spare cores</text>`;
    s += hostTiles(392, null, 0, 0);
    s += `<rect x="388" y="218" width="68" height="132" rx="10" fill="none" stroke="${C.yellow}" stroke-width="4" data-s="3" style="--d:300ms"/>`;
    s += `<rect x="392" y="380" width="20" height="20" rx="5" fill="${C.blue}"/><text class="t2" x="420" y="397">vLLM 8</text>`;
    s += `<rect x="512" y="380" width="20" height="20" rx="5" fill="${C.green}"/><text class="t2" x="540" y="397">CPU services 36</text>`;
    s += `<text class="t2" x="392" y="440">CPU services fill the spare cores</text>`;
    // accelerator host #2 (added in step 1)
    s += `<g data-s="1" style="--d:1300ms">${fbox(840, 120, 440, 360, C.ground, C.ink, 0.55)}<text class="t1" x="868" y="164">New accelerator host</text><text class="t2" x="868" y="196">added by GKE for vLLM</text>${tiles(872, 222, 12, 4, 32, () => "outline", null, 0)}</g>`;
    s += hostTiles(872, 1, 1800, 2300);
    s += `<text class="t2" data-s="1" style="--d:2600ms" x="872" y="440">waiting CPU pods land at once</text>`;
    // N4D (added in step 2)
    s += `<g data-s="2" style="--d:1300ms">${fbox(1320, 120, 344, 360, C.ground, C.ink, 0.55)}<text class="t1" x="1348" y="164">CPU nodes (N4D)</text><text class="t2" x="1348" y="196">overflow, paid only when used</text>${tiles(1352, 222, 8, 4, 36, () => "outline", null, 0)}</g>`;
    s += tiles(1352, 222, 8, 4, 36, (c, r) => (c * 4 + r < 6 ? "red" : null), 2, (c, r) => 1900 + (c * 4 + r) * 120);
    s += `<text class="t2" data-s="2" style="--d:2600ms" x="1352" y="440">the 6 pods run here</text>`;
    // guardrails
    s += fbox(360, 512, 1304, 88, mix("yellow", 16), C.yellow);
    s += `<text class="t1" x="388" y="552">Guardrails keep serving safe</text><text class="t2" x="388" y="584">exclusive cores for vLLM · memory-heavy work never on accelerator hosts · only serving uses GPU/TPU</text>`;
    // signals
    s += sig(1, 0, "M300,205 L356,205");
    s += sig(1, 300, "M470,120 L470,92", "request rate", 482, 112);
    s += sig(1, 1000, "M1060,88 L1060,116", "new node + vLLM", 1072, 112);
    s += sig(2, 0, "M300,396 L356,396");
    s += sig(2, 300, "M720,120 L720,92", "overflow metric", 732, 112);
    s += sig(2, 1000, "M1490,88 L1490,116", "new N4D node", 1502, 112);
    s += sig(3, 0, "M580,512 L580,484");
    s += sig(3, 0, "M1060,512 L1060,484");
    s += sig(3, 0, "M1490,512 L1490,484", "memory-heavy → N4D", 1478, 504, "end");
    return s;
  }
  function setStep(sl, k) {
    if (!sl || !sl.dataset.steps) return;
    const n = +sl.dataset.steps;
    k = Math.max(0, Math.min(n - 1, k));
    sl._step = k;
    $$("[data-s]", sl).forEach((e) => {
      const s = +e.dataset.s;
      e.classList.toggle("hide", s > k);
      e.classList.toggle("now", s === k);
      e.classList.toggle("past", s < k);
    });
    const shot = html.classList.contains("shot");
    $$(".steps li", sl).forEach((li) => li.classList.toggle("dim", !shot && k > 0 && +li.dataset.step !== k));
    $$(".st-dots button", sl).forEach((b, i) => (i === k ? b.setAttribute("aria-current", "step") : b.removeAttribute("aria-current")));
    const pv = $(".st-prev", sl), nx = $(".st-next", sl);
    if (pv) pv.disabled = k === 0;
    if (nx) nx.disabled = k === n - 1;
  }
  function initSteps(sl) {
    const n = +sl.dataset.steps, dots = $(".st-dots", sl);
    for (let i = 0; i < n; i++) {
      const b = document.createElement("button");
      b.type = "button";
      b.setAttribute("aria-label", i ? `Step ${i}` : "Overview");
      b.addEventListener("click", () => setStep(sl, i));
      dots.appendChild(b);
    }
    $(".st-prev", sl).addEventListener("click", () => setStep(sl, sl._step - 1));
    $(".st-next", sl).addEventListener("click", () => setStep(sl, sl._step + 1));
    setStep(sl, 0);
  }

  /* ------------------------------------------------------------ slide 5 */
  function guidance() {
    const g = (D.pricing || {}).guidance;
    const t = $("#gtable");
    if (!t) return;
    if (!g) { t.innerHTML = `<tr><td colspan="4"><span class="ph">placeholder</span> guidance.csv not landed yet</td></tr>`; return; }
    const opt = "3-yr CUD";
    const lv = [["light", "Light"], ["typical", "Typical"], ["full", "Full"]];
    let s = `<thead><tr><th>Avoided N4D spend<small>per host per month, ${opt} · % of host price</small></th>${lv.map(([k, n]) => `<th>${n}<small>${fmt(g.g4[opt][k].pct)} % of spare</small></th>`).join("")}</tr></thead><tbody>`;
    for (const [host, name, sub] of [["g4", "G4", "g4-standard-48"], ["v6e", "TPU v6e", "ct6e-standard-1t"]]) {
      const r = g[host][opt];
      s += `<tr><td><b>${name}</b>${sub} · $${fmt(r.light.host_hr, 2)}/hr</td>${lv.map(([k]) => `<td><b>$${fmt(r[k].usd_mo)}</b>${fmt(r[k].vcpu, 1)} vCPU · ${fmt(r[k].pct_host)} %</td>`).join("")}</tr>`;
    }
    t.innerHTML = s + "</tbody>";
    const m = (h) => g[h][opt].measured;
    $$("[data-g]").forEach((e) => {
      const [h, f] = e.dataset.g.split(".");
      const v = m(h)[f];
      e.textContent = f === "usd_mo" ? `$${fmt(v)}` : f === "pct_host" ? `${fmt(v)} %` : fmt(v);
    });
    const wy = (D.pricing || {}).what_you_get;
    if (wy) {
      $$("[data-w]").forEach((e) => { const f = e.dataset.w, v = wy[f]; e.textContent = f === "pct" ? `${fmt(Math.abs(v), 1)} %` : `$${fmt(v, 2)}`; });
      const fe = $("#wyg-fn"); if (fe) fe.textContent = wy.fn;
    }
    const a = (D.pricing || {}).aws;
    if (a) $$("[data-a]").forEach((e) => {
      const f = e.dataset.a, v = a[f];
      e.textContent = /hr|effective|3yr/.test(f) ? `$${fmt(v, 3)}` : f.startsWith("saving_pct") ? `${fmt(Math.abs(v) * (Math.abs(v) < 1 ? 100 : 1), 1)} %` : `${fmt(v, 1)} %`;
    });
  }

  /* ------------------------------------------------------------ boot */
  function inject() {
    $$("[data-svg]").forEach((e) => { const s = D.svgs[e.dataset.svg]; e.innerHTML = s || `<span class="ph">placeholder</span> ${e.dataset.svg}`; });
  }
  strip("#strip-g4", { l3: [8, 8, 8], vllm: [1, 2, 3, 4], reserve: [0, 23] });
  const CFG = (D.kpi && D.kpi.cfg) || { v6e_pods: 16, g4_pods: 18 };
  $$("[data-c]").forEach((e) => { const v = CFG[e.dataset.c]; if (v !== undefined) e.textContent = v; });
  // v6e: 22 cores = core 0 (reserve) + cores 1-4 (vLLM) + one core per backfill pod from core 5; the rest stays shared
  const v6Bf = Array.from({ length: CFG.v6e_pods }, (_, i) => 5 + i);
  const v6Shared = Array.from({ length: 22 }, (_, c) => c).filter((c) => c !== 0 && c > 4 && !v6Bf.includes(c));
  strip("#strip-v6e", { l3: [8, 7, 7], vllm: [1, 2, 3, 4], reserve: [0, ...v6Shared] });
  const H = [
    { name: "g4-standard-48 · G4", cpu: "AMD EPYC 9B45", cores: 24, l3: [8, 8, 8], l3mib: 32, mem: "180 GB", acc: "NVIDIA RTX PRO 6000", accMem: "96 GB GDDR7", accGB: 96, vllm: [1, 2, 3, 4], reserve: [0, 23], bf: 18 },
    { name: "ct6e-standard-1t · TPU v6e", cpu: "AMD EPYC 9B14", cores: 22, l3: [8, 7, 7], l3mib: 32, mem: "176 GiB", acc: "TPU v6e chip", accMem: "32 GiB HBM", accGB: 32, vllm: [1, 2, 3, 4], reserve: [0, ...v6Shared], bf: CFG.v6e_pods },
  ];
  $("#s2svg").innerHTML = hostSVG(H[0], 0) + hostSVG(H[1], 868);
  $("#s3svg").innerHTML = gkeSVG();
  $("#flowsvg").innerHTML = flowSVG();
  $$(".slide[data-steps]").forEach(initSteps);
  slides.forEach((sl, i) => { const pg = $(".pg", sl); if (pg) pg.textContent = sl.dataset.appendix ? `Appendix · ${i + 1} / ${slides.length}` : `${i + 1} / ${slides.length}`; });
  inject();
  $$("[data-k]").forEach((e) => { const [h, f] = e.dataset.k.split("."); const v = ((D.kpi || {})[h] || {})[f]; if (v !== undefined && v !== null) e.textContent = typeof v === "number" ? (/ready_pct/.test(f) && !Number.isInteger(v) ? fmt(v, 1) : fmt(v)) : v; });
  kpisExp();
  for (const acc of ["g4", "v6e"]) {
    const k = (D.kpi && D.kpi[acc]) || {};
    const a = $(`#kpi-${acc}-a`), b = $(`#kpi-${acc}-b`);
    if (a) a.innerHTML =
      cell(k.ttft_ratio ? `${fmt(k.ttft_ratio, 2)}×` : "–", k.ttft_ratio ? `TTFT p99 with the node full (${fmt(k.ttft_solo_ms)} → ${fmt(k.ttft_full_ms)} ms)` : "TTFT p99 with the node full") +
      cell(k.node_busy_full !== undefined ? `${fmt(k.node_busy_solo)} → ${fmt(k.node_busy_full)} %` : "–", "host CPU busy, vLLM alone → node full");
    if (b) b.innerHTML =
      cell(k.spike_covered_s ? `${fmt(k.spike_covered_s)} s` : "–", "CPU spike fully covered (N4D boot)") +
      cell(k.scale_ready_pct_all !== undefined ? `${fmt(k.scale_ready_pct_all, Number.isInteger(k.scale_ready_pct_all) ? 0 : 1)} %` : "–", "of the scale-out/in run with CPU pods Ready ≥ demand");
  }
  if (window.DeckReplay) {
    players.g4 = new window.DeckReplay.Player($("#rp-g4"), "g4", (D.replays || {}).g4);
    players.v6e = new window.DeckReplay.Player($("#rp-v6e"), "v6e", (D.replays || {}).v6e);
  }
  guidance();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => html.classList.add("fonts-ready"));
  fromHash();
})();
